  "p9-nginx-tls": {"distro":"Ubuntu 24.04","cmd":"curl -s --resolve shop.example.com:443:127.0.0.1 https://shop.example.com; echo \"exit: $?\"; curl -s --cacert /etc/ssl/certs/shop.crt --resolve shop.example.com:443:127.0.0.1 https://shop.example.com","out":"exit: 60\nWelcome to the shop\n","setup":"openssl req -x509 -newkey rsa:2048 -nodes -keyout /etc/ssl/private/shop.key -out /etc/ssl/certs/shop.crt -days 365 -subj '/CN=shop.example.com' -addext 'subjectAltName=DNS:shop.example.com' 2>/dev/null; printf 'server {\\n    listen 443 ssl;\\n    server_name shop.example.com;\\n    ssl_certificate /etc/ssl/certs/shop.crt;\\n    ssl_certificate_key /etc/ssl/private/shop.key;\\n    root /var/www/shop;\\n}\\n' > /etc/nginx/sites-available/shop-tls; ln -sf /etc/nginx/sites-available/shop-tls /etc/nginx/sites-enabled/shop-tls; nginx -t && systemctl reload nginx; sleep 1"},
