  "p9-tz-files": {"distro":"Ubuntu 24.04","cmd":"ls -l /etc/localtime | awk '{print $9, $10, $11}'; timedatectl set-timezone Etc/UTC","out":"/etc/localtime -> /usr/share/zoneinfo/Asia/Jerusalem\n","setup":"timedatectl set-timezone Asia/Jerusalem"},
  "p9-upstream": {"distro":"Ubuntu 24.04","cmd":"for i in 1 2 3 4; do curl -s -H 'Host: lb.example.com' http://127.0.0.1; done","out":"app 1 answered\napp 2 answered\napp 1 answered\napp 2 answered\n","setup":"for n in 1 2; do mkdir -p /srv/app$n; echo \"app $n answered\" > /srv/app$n/index.html; (cd /srv/app$n && setsid nohup python3 -m http.server 900$n --bind 127.0.0.1 >/dev/null 2>&1 &); done; printf 'upstream shop_apps {\\n    zone shop_apps 64k;\\n    server 127.0.0.1:9001;\\n    server 127.0.0.1:9002;\\n}\\nserver {\\n    listen 80;\\n    server_name lb.example.com;\\n    location / {\\n        proxy_pass http://shop_apps;\\n    }\\n}\\n' > /etc/nginx/sites-available/lb; ln -sf /etc/nginx/sites-available/lb /etc/nginx/sites-enabled/lb; nginx -t && systemctl reload nginx; sleep 2; ss -ltn | grep -E \":900[12]\""},
